(()=>{const supported=new Set(['he','en','ru','ar']);const url=new URL(location.href);const q=url.searchParams.get('lang');if(!supported.has(q))return;const parts=url.pathname.split('/').filter(Boolean);const current=supported.has(parts[0])?parts[0]:'he';if(q===current){url.searchParams.delete('lang');history.replaceState(null,'',url.pathname+(url.searchParams.toString()?'?'+url.searchParams.toString():'')+url.hash);return;}const rest=supported.has(parts[0])?parts.slice(1):parts;url.pathname=q==='he'?'/'+(rest.length?rest.join('/')+'/':''):'/'+q+'/'+(rest.length?rest.join('/')+'/':'');url.searchParams.delete('lang');location.replace(url.pathname+(url.searchParams.toString()?'?'+url.searchParams.toString():'')+url.hash);})();